KG42.register("functional_groups-93df157b1902af9ef1031412",{"id":"COMP-488e4abbbcabfe42","code":"OMC031","definition":"A designated operator bears responsibility for organizing clearing of the local market under its jurisdiction: on the basis of the market information and operating conditions prescribed by that mechanism, it organizes and carries out the processing that forms the market-clearing result. Its specific duties of configuration, price, and result delivery are retained as member specializations.","layer":"L4","template_code":"JOC","child_ids":["KG40-45833afd23977831","KG40-fe5714e5a1d65999","KG40-d5743b8980847a21","KG40-929f1d15e71305ba"],"active_graph_node":false,"role":"Functional group context; not an additional active graph node"});
